"""Generated byte files and simulated native loaders; no SDK payload reads.

Actual Python import dispatch exercises success and failure callbacks, while
patched ExtensionFileLoader methods never ask the OS to load a shared library.
"""
import copy
import hashlib
import importlib
import importlib.machinery as machinery
import importlib.util
import os
from pathlib import Path
import sys
import tempfile
import types
import unittest
from unittest.mock import patch

sys.path.insert(0,str(Path(__file__).resolve().parent))
import nemotron4b_native_origin_audit_v1 as native
import nemotron4b_import_router_v4 as routing


def mapped(path='',*,begin=4096,permissions='r-xp',inode=0,device=(0,0)):
    return (f'{begin:x}-{begin+4096:x} {permissions} 00000000 '
            f'{device[0]:02x}:{device[1]:02x} {inode}'+(' '+str(path)if path else '')+'\n')


KERNEL=mapped('[vdso]',begin=65536)


class Maps(unittest.TestCase):
    def test_spaces_and_non_linebreak_unicode_preserve_literal_path(self):
        path='/tmp/native name\u2028.so'
        self.assertEqual(native.parse_maps(mapped(path))[0]['path'],path)

    def test_newline_escape_is_ambiguous_and_rejected(self):
        with self.assertRaises(ValueError):native.parse_maps(mapped('/tmp/a\\012.so'))

    def test_invalid_maps_and_overlaps_are_rejected(self):
        bad=['','\n',mapped()+mapped(),mapped(begin=8192)+mapped(),
             '1000-1000 r-xp 00 00:00 0\n','1000-2000 rwxq 00 00:00 0\n',
             '1000-2000 r-xp zz 00:00 0\n','1000-2000 r-xp 00 00:00 -1\n',
             mapped('/tmp/a\x00.so'),mapped()+'\n']
        for text in bad:
            with self.subTest(text=text),self.assertRaises(ValueError):native.parse_maps(text)

    def test_maps_byte_and_row_budgets(self):
        with patch.object(native,'MAP_CAP',3),self.assertRaises(ValueError):
            native.parse_maps(mapped())
        with self.assertRaises(ValueError):
            native.parse_maps(''.join(mapped(begin=4096*(i+1))for i in range(32769)))


class Fixture(unittest.TestCase):
    def setUp(self):
        self.tmp=tempfile.TemporaryDirectory(prefix='nano-native-origin-fixture-')
        self.addCleanup(self.tmp.cleanup)
        self.root=Path(self.tmp.name).resolve()
        self.path=self.root/'generated.so'
        self.payload=b'generated nonexecutable native fixture\x00'*31
        self.path.write_bytes(self.payload)
        self.row=dict(path=str(self.path),bytes=len(self.payload),
                      sha256=hashlib.sha256(self.payload).hexdigest(),
                      fullstat=native.fullstat(self.path.stat()))
        self.expected={str(self.path):self.row}

    def files(self,guard=lambda:None):
        return native.NativeFiles(self.expected,native_read_guard=guard)


class Files(Fixture):
    def test_authenticate_complete_bytes_and_return_copy(self):
        files=self.files();record=files.authenticate(str(self.path))
        self.assertEqual(record['sha256'],self.row['sha256'])
        self.assertEqual(record['bytes'],len(self.payload))
        record['sha256']='0'*64
        files.require_complete()

    def test_guard_denial_before_open_and_after_open_closes_fd(self):
        def deny():raise RuntimeError('serial slot unavailable')
        with patch.object(native.os,'open',wraps=os.open)as opened:
            with self.assertRaisesRegex(RuntimeError,'serial slot'):self.files(deny).authenticate(str(self.path))
            opened.assert_not_called()
        count=0
        def later():
            nonlocal count
            count+=1
            if count==2:deny()
        with patch.object(native.os,'close',wraps=os.close)as close:
            files=self.files(later)
            with self.assertRaisesRegex(RuntimeError,'serial slot'):files.authenticate(str(self.path))
            fd=close.call_args.args[0]
            with self.assertRaises(OSError):os.fstat(fd)
            self.assertEqual(files.verified,{})

    def test_hash_mismatch_closes_fd_and_cannot_authorize(self):
        self.row['sha256']='0'*64;files=self.files()
        with patch.object(native.os,'close',wraps=os.close)as close:
            with self.assertRaises(ValueError):files.authenticate(str(self.path))
            with self.assertRaises(OSError):os.fstat(close.call_args.args[0])
        with self.assertRaises(ValueError):files.require_complete()

    def test_catalog_is_snapshotted(self):
        files=self.files();self.row['sha256']='0'*64
        files.authenticate_all();files.require_complete()

    def test_mutation_during_hash_rejected_even_if_size_unchanged(self):
        count=0
        def guard():
            nonlocal count
            count+=1
            if count==3:
                self.path.write_bytes(b'x'*len(self.payload))
                os.utime(self.path,ns=(0,self.row['fullstat']['st_mtime_ns']+1000000000))
        files=self.files(guard)
        with self.assertRaises(ValueError):files.authenticate_all()
        self.assertEqual(files.verified,{})

    def test_replacement_during_hash_rejected(self):
        replacement=self.root/'replacement';replacement.write_bytes(self.payload)
        count=0
        def guard():
            nonlocal count
            count+=1
            if count==3:os.replace(replacement,self.path)
        with self.assertRaises(ValueError):self.files(guard).authenticate_all()

    def test_changed_identity_after_authentication_rejected(self):
        files=self.files();files.authenticate_all();self.path.write_bytes(b'x'*len(self.payload))
        os.utime(self.path,ns=(0,self.row['fullstat']['st_mtime_ns']+1000000000))
        with self.assertRaises(ValueError):files.require_complete()

    def test_failed_reauthentication_revokes_prior_success(self):
        files=self.files();files.authenticate_all()
        def deny():raise RuntimeError('denied')
        files.native_read_guard=deny
        with self.assertRaises(RuntimeError):files.authenticate_all()
        with self.assertRaises(ValueError):files.require_complete()

    def test_partial_catalog_cannot_authorize_mapping(self):
        second=self.root/'second';second.write_bytes(self.payload)
        self.expected[str(second)]=dict(self.row,path=str(second),fullstat=native.fullstat(second.stat()))
        files=self.files();files.authenticate(str(self.path))
        with self.assertRaises(ValueError):files.require_complete()

    def test_original_hardlink_count_is_supported(self):
        os.link(self.path,self.root/'alias')
        self.row['fullstat']=native.fullstat(self.path.stat())
        files=self.files();files.authenticate_all();files.require_complete()

    def test_symlink_path_is_not_implicitly_authorized(self):
        link=self.root/'link.so';link.symlink_to(self.path)
        self.expected={str(link):dict(self.row,path=str(link))}
        with self.assertRaises(ValueError):self.files().authenticate_all()

    def test_oversized_or_zero_payload_rejected_before_read(self):
        for size in [0,native.FILE_CAP+1]:
            self.row['bytes']=size;self.row['fullstat']['st_size']=size
            with self.assertRaises(ValueError):self.files()


class MappingAndLifecycle(Fixture):
    def setUp(self):
        super().setUp()
        self.checked=self.files();self.checked.authenticate_all()
        self.maps=KERNEL
        self.audit=native.NativeMappingAudit(self.checked,read_maps=lambda:self.maps,
                         approved_kernel_exec=native.parse_maps(KERNEL))

    def file_map(self,**overrides):
        s=self.path.stat()
        args=dict(path=self.path,inode=s.st_ino,device=(os.major(s.st_dev),os.minor(s.st_dev)))
        args.update(overrides)
        return mapped(**args)

    def test_known_exec_and_partial_readonly_shared_mapping(self):
        for permissions in ['r-xp','r--p']:
            self.maps=self.file_map(permissions=permissions)+KERNEL
            self.assertEqual(self.audit.audit()['paths'],[str(self.path)])

    def test_unknown_executable_and_partial_shared_mapping_rejected(self):
        for path,perms in [('/tmp/unknown.bin','r-xp'),('/tmp/unknown.so.1','r--p')]:
            self.maps=mapped(path,permissions=perms)+KERNEL
            with self.assertRaises(ValueError):self.audit.audit()

    def test_deleted_mapping_rejected(self):
        self.maps=self.file_map(path=str(self.path)+' (deleted)',permissions='r--p')+KERNEL
        with self.assertRaisesRegex(ValueError,'deleted'):self.audit.audit()

    def test_wrong_device_or_inode_rejected(self):
        for override in [dict(inode=self.path.stat().st_ino+1),dict(device=(0,0))]:
            self.maps=self.file_map(**override)+KERNEL
            with self.assertRaisesRegex(ValueError,'device/inode'):self.audit.audit()

    def test_anonymous_executable_and_changed_kernel_rejected(self):
        for text in [mapped()+KERNEL,mapped('[anon:jit]')+KERNEL,
                     mapped('[vdso]',begin=131072),mapped('[heap]',permissions='rw-p')]:
            self.maps=text
            with self.assertRaisesRegex(ValueError,'anonymous executable'):self.audit.audit()

    def test_nonexecuting_data_maps_need_no_native_catalog_entry(self):
        self.maps=mapped('/tmp/data.bin',permissions='rw-p')+KERNEL
        self.assertEqual(self.audit.audit()['paths'],[])

    def test_deduplicated_snapshots_do_not_disable_audit_budget(self):
        self.audit.audit();self.audit.audit()
        self.assertEqual(len(self.audit.snapshots),1)
        self.audit.audit_count=4096
        with self.assertRaises(ValueError):self.audit.audit()

    def run_import(self,create=None,execute=None,mutate_selected=None):
        name='_nano_generated_native_fixture'
        path=str(self.path)
        loader=machinery.ExtensionFileLoader(name,path)
        spec=importlib.util.spec_from_file_location(name,path,loader=loader)
        class Finder:
            def find_spec(finder,fullname,search=None,target=None):
                return spec if fullname==name else None
        finder=Finder()
        router=routing.ImportRouter(finders=[finder],modules={name:dict(self.row,kind='native')},
            namespaces={},guard=lambda:None,authorize_finder=lambda f:None,
            authorize_builtin=lambda *a:None,authorize_native=self.audit.authorize_native,
            authorize_custom=lambda *a:None)
        self.router=router
        self.selected_spec=spec
        self.addCleanup(sys.modules.pop,name,None)
        def make(original,effective):
            return create(effective)if create else types.ModuleType(name)
        def perform(original,module):
            if execute:execute(module)
            else:module.answer=42
        # Only synthetic Python methods execute. No dlopen/native extension call.
        with patch.object(machinery.ExtensionFileLoader,'create_module',make), \
             patch.object(machinery.ExtensionFileLoader,'exec_module',perform), \
             patch.object(sys,'meta_path',[router]):
            if mutate_selected:
                selected=router.find_spec(name)
                mutate_selected(selected)
                module=importlib.util.module_from_spec(selected)
                selected.loader.exec_module(module)
                return module
            return importlib.import_module(name)

    def test_cpython_loader_success_checks_create_and_exec(self):
        module=self.run_import()
        self.assertEqual(module.answer,42)
        self.assertEqual([x['phase']for x in self.audit.calls],['create','exec'])
        self.assertFalse(self.router.poisoned)

    def test_ordinary_optional_importerror_preserved_and_failure_audited(self):
        for phase in ['create','exec']:
            with self.subTest(phase=phase):
                error=ImportError('optional native feature absent')
                def fail(value):raise error
                with self.assertRaises(ImportError)as raised:
                    self.run_import(**{('create'if phase=='create'else 'execute'):fail})
                self.assertIs(raised.exception,error)
                self.assertEqual(self.audit.calls[-1]['phase'],phase+'_failed')
                self.assertFalse(self.router.poisoned)

    def test_failed_initialization_leaves_unknown_mapping_and_poisons_router(self):
        for phase in ['create','exec']:
            with self.subTest(phase=phase):
                self.maps=KERNEL
                def fail(value):
                    self.maps=mapped('/tmp/unexpected.so',permissions='r--p')+KERNEL
                    raise ImportError('partial initialization')
                with self.assertRaises(routing.ProvenanceError):
                    self.run_import(**{('create'if phase=='create'else 'execute'):fail})
                self.assertTrue(self.router.poisoned)
                with self.assertRaises(routing.ProvenanceError):self.router.check()

    def test_successful_initializer_unexpected_mapping_is_rejected(self):
        def execute(module):self.maps=mapped('/tmp/unexpected.so')+KERNEL
        with self.assertRaises(routing.ProvenanceError):self.run_import(execute=execute)
        self.assertTrue(self.router.poisoned)

    def test_original_exit_value_survives_failed_mapping_audit(self):
        def execute(module):
            self.maps=mapped('/tmp/unexpected.so')+KERNEL
            raise SystemExit(23)
        with self.assertRaises(SystemExit)as raised:self.run_import(execute=execute)
        self.assertEqual(raised.exception.code,23)
        self.assertTrue(self.router.poisoned)

    def test_selected_spec_inplace_mutation_rejected_before_initializer(self):
        for field,value in [('origin','/tmp/other.so'),('name','other'),
                            ('submodule_search_locations',[]),('loader_state',object())]:
            with self.subTest(field=field):
                called=[]
                with self.assertRaises(routing.ProvenanceError):
                    self.run_import(create=lambda spec:called.append(1),
                                    mutate_selected=lambda spec:setattr(spec,field,value))
                self.assertEqual(called,[])

    def test_spec_replacement_during_exec_rejected(self):
        def execute(module):module.__spec__=copy.copy(module.__spec__)
        with self.assertRaises(routing.ProvenanceError):self.run_import(execute=execute)
        self.assertTrue(self.router.poisoned)


if __name__=='__main__':unittest.main(verbosity=2)
